    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1, 2]), fmt([7, 7]), fmt([4, 4, 4, 4, 8, 3, 5, 9]), fmt([10, 20, 30, 1, 2, 3]), fmt([-5, 5, -5, 5]),
             fmt([10**9, -10**9])]
    for n in (2, 4, 6, 10, 16, 24, 40):
        for _ in range(2):
            tests.append(fmt([rng.randint(-100, 100) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.randint(0, 3) for _ in range(N)]))
    tests.append(fmt(list(range(N))))
    return tests

